package br.com.erp;
import com.fasterxml.jackson.databind.JsonNode;
import java.math.BigDecimal;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class SaleTest extends SaleFixture {
 @Test void cashSaleRoundsEachItemAndPostsNetCashAndStock()throws Exception{var s=sell(input(UUID.randomUUID(),"1.5","10.25","20"),201);money("15.38",s.get("total"));money("4.62",s.get("changeAmount"));assertEquals(0,new BigDecimal("8.5").compareTo(quantity(product)));assertEquals(0,new BigDecimal("15.38").compareTo(balance()));assertEquals(1,getApi("/api/v1/pos/cash-sessions/"+session,auth,200).get("version").asInt());assertEquals("POS_SALE",getApi("/api/v1/treasury/accounts/"+account+"/entries",auth,200).get("items").get(0).get("origin").asText());}
 @Test void historyPreservesPriceNameUnitAndReplayAfterClose()throws Exception{var body=input(UUID.randomUUID(),"1","10.25","20");var sale=sell(body,201);postApi("/api/v1/pos/cash-sessions/"+session+"/close",auth,Map.of("requestId",UUID.randomUUID(),"version",1,"countedAmount","10.25","note","Contagem final de teste"),200);db.update("UPDATE product SET sale_price=99,name='Alterado',unit='UN',active=FALSE WHERE tenant_id=? AND id=?",tenant,UUID.fromString(product));assertEquals(sale,getApi("/api/v1/pos/sales/"+sale.get("id").asText(),auth,200));assertEquals(sale,sell(body,201));assertEquals(1,count("pos_sale"));}
 @Test void staleOrTamperedPriceCannotDebitStock()throws Exception{sell(input(UUID.randomUUID(),"1","0.01","20"),409);db.update("UPDATE product SET sale_price=11 WHERE tenant_id=? AND id=?",tenant,UUID.fromString(product));sell(input(UUID.randomUUID(),"1","10.25","20"),409);assertEquals(0,count("pos_sale"));assertEquals(0,BigDecimal.TEN.compareTo(quantity(product)));assertEquals(0,balance().signum());}
 @Test void equivalentScalesReplayAndDifferentTenderConflicts()throws Exception{UUID key=UUID.randomUUID();var a=sell(input(key,"1","10.25","20"),201);assertEquals(a,sell(input(key,"1.000000","10.25","20.00"),201));sell(input(key,"1","10.25","21"),409);assertEquals(1,count("pos_sale"));assertEquals(2,count("stock_operation"));}
 @Test void insufficientSecondItemRollsBackFirstItemAndCash()throws Exception{String second=createProduct("SECOND","5");stock(second,"1");sell(Map.of("requestId",UUID.randomUUID(),"sessionId",session,"tendered","100","items",List.of(item(product,"1","10.25"),item(second,"2","5"))),409);assertEquals(0,BigDecimal.TEN.compareTo(quantity(product)));assertEquals(0,BigDecimal.ONE.compareTo(quantity(second)));assertEquals(0,count("pos_sale"));assertEquals(0,count("treasury_operation"));assertEquals(2,count("stock_operation"));}
 @Test void insufficientTenderAndDuplicateProductsHaveNoEffects()throws Exception{sell(input(UUID.randomUUID(),"1","10.25","10"),400);sell(Map.of("requestId",UUID.randomUUID(),"sessionId",session,"tendered","100","items",List.of(item(product,"1","10.25"),item(product,"1","10.25"))),400);sell(input(UUID.randomUUID(),"0","10.25","20"),400);assertEquals(0,count("pos_sale"));}
 @Test void inactiveWarehouseAndProductPreventSale()throws Exception{db.update("UPDATE warehouse SET active=FALSE WHERE tenant_id=? AND id=?",tenant,UUID.fromString(warehouse));sell(input(UUID.randomUUID(),"1","10.25","20"),409);db.update("UPDATE warehouse SET active=TRUE WHERE tenant_id=? AND id=?",tenant,UUID.fromString(warehouse));db.update("UPDATE product SET active=FALSE WHERE tenant_id=? AND id=?",tenant,UUID.fromString(product));sell(input(UUID.randomUUID(),"1","10.25","20"),404);assertEquals(0,count("pos_sale"));}
 @Test void warehouseBindingRequiresClosedSessionCurrentVersionSameBranch()throws Exception{bind(warehouse,1,409);postApi("/api/v1/pos/cash-sessions/"+session+"/close",auth,Map.of("requestId",UUID.randomUUID(),"version",0,"countedAmount","0","note","Fechamento do teste"),200);bind(warehouse,0,409);UUID other=UUID.fromString(postApi("/api/v1/branches",auth,Map.of("code","B","name","Outra"),201).get("id").asText());String wrong=postApi("/api/v1/inventory/warehouses",auth,Map.of("branchId",other,"code","W","name","Outro"),201).get("id").asText();bind(wrong,1,400);bind(warehouse,1,200);}
 @Test void closedAndUnconfiguredSessionsCannotSell()throws Exception{db.update("UPDATE pos_terminal SET warehouse_id=NULL WHERE tenant_id=? AND id=?",tenant,UUID.fromString(terminal));sell(input(UUID.randomUUID(),"1","10.25","20"),409);db.update("UPDATE pos_terminal SET warehouse_id=? WHERE tenant_id=? AND id=?",UUID.fromString(warehouse),tenant,UUID.fromString(terminal));postApi("/api/v1/pos/cash-sessions/"+session+"/close",auth,Map.of("requestId",UUID.randomUUID(),"version",0,"countedAmount","0","note","Fechamento do teste"),200);sell(input(UUID.randomUUID(),"1","10.25","20"),409);}
 @Test void saleHistoryAndReplayRespectTenantAndBranchScope()throws Exception{var body=input(UUID.randomUUID(),"1","10.25","20");var s=sell(body,201);String path="/api/v1/pos/sales/"+s.get("id").asText();String other="other-"+UUID.randomUUID();provisioning.create("Outra",other,"Admin","admin@example.com",password);getApi(path,token(other),404);db.update("UPDATE app_user SET all_branches=FALSE WHERE tenant_id=?",tenant);getApi(path,auth,404);assertEquals(0,getApi("/api/v1/pos/sales",auth,200).get("total").asInt());sell(body,404);}
 @Test void permissionAndOwnerChecksApplyToSales()throws Exception{var u=postApi("/api/v1/users",auth,Map.of("name","Outro","email","other@example.com","password",password,"permissions",List.of("pos:read","pos:sell","treasury:read","treasury:move")),201);String other=postApi("/api/v1/auth/login",null,Map.of("company",company,"email","other@example.com","password",password),200).get("token").asText();var body=input(UUID.randomUUID(),"1","10.25","20");postApi("/api/v1/pos/sales",other,body,403);db.update("INSERT INTO user_permission(tenant_id,user_id,permission) VALUES(?,?,'pos:supervise')",tenant,UUID.fromString(u.get("id").asText()));postApi("/api/v1/pos/sales",other,body,201);db.update("DELETE FROM user_permission WHERE tenant_id=? AND permission='pos:sell'",tenant);sell(input(UUID.randomUUID(),"1","10.25","20"),403);}
 @Test void cashOverflowRollsBackStockAndSale()throws Exception{db.update("UPDATE treasury_account SET balance=99999999999999999.99 WHERE tenant_id=? AND id=?",tenant,UUID.fromString(account));sell(input(UUID.randomUUID(),"1","10.25","20"),409);assertEquals(0,BigDecimal.TEN.compareTo(quantity(product)));assertEquals(1,count("stock_operation"));assertEquals(0,count("pos_sale"));}
 @Test void concurrentRetryHasOneEffectAndOversellingIsRejected()throws Exception{var body=input(UUID.randomUUID(),"6","10.25","100");assertEquals(List.of(201,201),race(body,body));assertEquals(List.of(409,409),race(input(UUID.randomUUID(),"6","10.25","100"),input(UUID.randomUUID(),"6","10.25","100")));assertEquals(1,count("pos_sale"));assertEquals(0,new BigDecimal("4").compareTo(quantity(product)));}
 @Test void competingSalesCannotOversellAvailableQuantity()throws Exception{assertEquals(List.of(201,409),race(input(UUID.randomUUID(),"6","10.25","100"),input(UUID.randomUUID(),"6","10.25","100")));assertEquals(1,count("pos_sale"));assertEquals(0,new BigDecimal("4").compareTo(quantity(product)));assertEquals(0,new BigDecimal("61.50").compareTo(balance()));}
 @Test void closingRaceWithSaleCannotLoseCashOrStock()throws Exception{var body=input(UUID.randomUUID(),"1","10.25","20");try(var pool=Executors.newFixedThreadPool(2)){var gate=new CountDownLatch(1);var a=pool.submit(()->{gate.await();return status("/api/v1/pos/sales",body);});var b=pool.submit(()->{gate.await();return status("/api/v1/pos/cash-sessions/"+session+"/close",Map.of("requestId",UUID.randomUUID(),"version",0,"countedAmount","0","note","Fechamento concorrente"));});gate.countDown();var result=new ArrayList<>(List.of(a.get(30,TimeUnit.SECONDS),b.get(30,TimeUnit.SECONDS)));Collections.sort(result);assertTrue(result.equals(List.of(200,409))||result.equals(List.of(201,409)));var s=getApi("/api/v1/pos/cash-sessions/"+session,auth,200);if(s.get("status").asText().equals("CLOSED")){assertEquals(0,count("pos_sale"));assertEquals(0,balance().signum());}else{assertEquals(1,count("pos_sale"));assertEquals(1,s.get("version").asInt());}}}
}
